head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.visuShrsLabelNm = "주식";
scwin.strCbd_NPARVALSTK_YN = "N^아니오,Y^예";
scwin.secugrpId ="";
scwin.market = $c.session.getUserInfo("market");

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — searchCode, setComboCode, setInitLabel, setSumblComponent, setPanelPREFSTK, setPREFSTKItem 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload =  async function() {
    try {

        // 초기화함수

        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92026.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출).
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    const  parentWin = $c.win.getParent();
    const  rowData = $c.data.getParameter("rowData");
    scwin.secugrpId = $c.data.getParameter("secugrpId");
    // scwin.market = '1'

    if ((scwin.market === "1" || scwin.market === "6")
            && scwin.secugrpId === "ST" || scwin.secugrpId === "DR" || scwin.secugrpId === "FS") {
        grp_duty.show();
    } else {
        grp_duty.hide();
    }

    scwin.vBzProcsNo = rowData.bzProcsNo;

    scwin.vSecugrpID = parentWin.sbx_SECUGRP_ID.getValue();
    scwin.vSPOT_ISU_TRD_MKT_TP_CD = parentWin.sbx_SPOT_ISU_TRD_MKT_TP_CD.getValue();

    // $c.stf.setObjectValue(ibx_ISUR_CD, $c.stf.getObjectValue(parentWin.ibx_ISUR_CD));
    ibx_ISUR_CD.setValue(parentWin.ibx_ISUR_CD.getValue());
    // $c.stf.setObjectValue(ibx_COM_NM, $c.stf.getObjectValue(parentWin.ibx_COM_NM));
    ibx_COM_NM.setValue(parentWin.ibx_COM_NM.getValue());

    rowPos = parentWin.grd_IssList.getFocusedRowIndex();

    await scwin.searchCode();

    await scwin.setComboCode();

    scwin.setInitLabel();
    scwin.setSumblComponent();
    scwin.setPanelPREFSTK(false); // 일단 false;
    scwin.setPREFSTKItem(false); // 일단 false;

    if (scwin.vBzProcsNo !== "") { // 수정
        await scwin.readSync();
        // 보호예수읽어온다
        await scwin.prtdepoReadSync();
    } else { // 신규
        if (ibx_ISUR_CD.getValue() === "") {

        } else {
            ibx_LIST_DD.setValue(parentWin.ica_LIST_DD.getValue()); // 상장일
            let vlistClssCd =parentWin.sbx_LIST_CLSS_CD.getValue(); // 상장구분
            let vListMethdTpCd;
            let vListMethdTpUpCd = vlistClssCd.substring(0, 1);
            if ( vListMethdTpUpCd === '1' ) {
                vListMethdTpCd = $c.lc.getGlbValue("LIST_METHD_TP_CD_4"); // 신규상장
            } else if (vListMethdTpUpCd === '2') {
                vListMethdTpCd = $c.lc.getGlbValue("LIST_METHD_TP_CD_5"); // 재상장
            }
            sbx_LIST_METHD_TP_CD.setValue(vListMethdTpCd);
        }

        let vCurDate = $c.date.getServerDateTime();

        if (ibx_LIST_DD.getValue() <= vCurDate) {
            btn_Delete.setDisabled(true);
            btn_Update.setDisabled(true);
            // btn_Save.setDisabled(true);
        }

        if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === '1') {
            // 자동 settiong
            panel_ISU_ENG_SYMBL.show();
            ibx_ISU_ENG_SYMBL.setValue(parentWin.ibx_ISUR_SYMBL.getValue())
        } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === '2' || scwin.vSPOT_ISU_TRD_MKT_TP_CD === '6') {
            panel_ISU_ENG_SYMBL.hide();
        }

        // 보호예수초기화
        scwin.prtdepoReadSyncSetHeader();
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ibx_PARVAL_OnKillFocus
 * @description ibx_PARVAL 포커스 이탈 — 입력값 검증·포맷
 * @returns {void}
 * @hidden N
 */
scwin.ibx_PARVAL_OnKillFocus = function() {
    try {
        if (sbx_NPARVALSTK_YN.getValue() === 'N' || sbx_NPARVALSTK_YN.getValue() === '') {
            scwin.calcusuCap();
            scwin.calcuAccIsuCap();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92026.ibx_PARVAL_OnKillFocus" });
    }
};

/**
 * @method
 * @name sbx_STK_ISU_RSN_CD_onselchange
 * @description sbx_STK_ISU_RSN_CD 선택 변경 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.sbx_STK_ISU_RSN_CD_onselchange = function() {
    try {
        scwin.calcuAccIsuShrs();
        if (sbx_NPARVALSTK_YN.getValue() === 'N' || sbx_NPARVALSTK_YN.getValue() === '') {
            scwin.calcuAccIsuCap();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92026.sbx_STK_ISU_RSN_CD_onselchange" });
    }
};

