/**
 * @method
 * @name img_ISU_CD_onclick
 * @description 종목코드 팝업클릭
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_ISU_CD_onclick = async function() {
    try {
        const isurCd = ibx_ISUR_CD.getValue();
        const res = await $c.lc.popFindNewIsuOfIsur(scwin.secugrpId, isurCd);

        if (res.isuCd !== ""){

            ibx_ISU_CD.setValue(res.isuCd);
            ibx_ISU_SRT_CD.setValue(res.isuSrtCd);
            ibx_ISU_KOR_NM.setValue(res.isuNm);
            ibx_ISU_KOR_ABBRV.setValue(res.isuSnm); // 종목약어명
            ibx_ISU_ENG_NM.setValue(res.isuEngNm); // 영문종목명
            ibx_ISU_ENG_ABBRV.setValue(res.isuEngSnm) // 영문약어명
            ibx_ISU_ENG_SYMBL.setValue(res.isuEngSymbl); // 심볼명
            ibx_ISU_RND.setValue(res.isuRnd); // 발행회차
            ica_ISU_DD.setValue(res.isuDd); // 발행일자
            sbx_CURR_ISO_CD.setValue(res.currIsoCd)  // 통화

            if (scwin.vSecugrpID === $c.lc.getGlbValue("SECUGRP_ID_DR")) {
                sbx_STKCERT_KIND_CD.setValue('KDR'); // 주식의종류코드를 셋팅
            } else if (scwin.vSecugrpID === $c.lc.getGlbValue("SECUGRP_ID_FS")) {
                sbx_STKCERT_KIND_CD.setValue('000'); // 주식의종류코드를 셋팅
            } else {
                let isurCd = ibx_ISUR_CD.getValue();
                sbx_STKCERT_KIND_CD.setValue(isurCd.substring(8, 11));
            }
            await scwin.setPREFSTKEvent(); // 셀렉트 박스제어
            await scwin.nprefstkReadSync(ibx_ISU_CD.getValue()); // 신형우선주 내역 조회
            await scwin.bfReadSync(); // 변경 전 주식수 및 자본금 조회
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92026.img_ISU_CD_onclick" });
    }
};

/**
 * @method
 * @name chk_PREFSTK_TP_CD_onclick
 * @description 신형주,우선여부체크
 * @returns {void}
 * @hidden N
 */
scwin.chk_PREFSTK_TP_CD_onclick = function() {
    try {
        if (chk_PREFSTK_TP_CD.getValue() === "Y") {
            scwin.setPanelPREFSTK(true);
            chk_PREFSTK_TP_CD.setValue("Y");
        } else {
            scwin.setPanelPREFSTK(false);
            chk_PREFSTK_TP_CD.setValue("");
        }
        panel_Item.focus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92026.chk_PREFSTK_TP_CD_onclick" });
    }
};

/**
 * @method
 * @name chk_INDEFINPD_YN_onclick
 * @description chk_INDEFINPD_YN 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.chk_INDEFINPD_YN_onclick = function() {
    try {
        if (chk_PREFSTK_TP_CD.checked) {
            ibx_PREFSTK_CONTIN_DEADLINE_YYS.setValue('');
            ibx_PREFSTK_CONTIN_DEADLINE_MM.setValue('');
            ibx_PREFSTK_CONTIN_DEADLINE_DYS.setValue('');
            ibx_PREFSTK_END_DD.setValue('');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92026.chk_INDEFINPD_YN_onclick" });
    }
};

/**
 * @method
 * @name img_IsuNmGuide_onclick
 * @description 「종목명 입력기준안내」 버튼 클릭
 * @returns {void}
 * @hidden N
 */
scwin.img_IsuNmGuide_onclick = function() {
    try {
        $c.lc.openDetailInputGuide();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92026.img_IsuNmGuide_onclick" });
    }
};

/**
 * @method
 * @name img_ISU_ENG_SYMBL_onclick
 * @description 중복체크 — 「중복체크」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_ISU_ENG_SYMBL_onclick = async function() {
    try {
        if (ibx_ISU_ENG_SYMBL.getValue() === "") {
            $c.win.alert("[영문종목심볼]을 입력하세요.");
            ibx_ISU_ENG_SYMBL.focus();
            return false;
        } else {
            if (await $c.lc.engSymblCheck(ibx_ISU_ENG_SYMBL.getValue())) {
                await $c.lc.chkCorpSymblDoubleInput1(ibx_ISU_ENG_SYMBL.getValue(), ibx_ISUR_CD.getValue());
                    if ($c.lc.getGlbValue("MSG_SYMBL_DOUBLE_INPUT")) {
                        $c.win.alert($c.lc.getGlbValue("MSG_SYMBL_DOUBLE_INPUT"));
                }
            } else {
                ibx_ISU_ENG_SYMBL.focus();
                return false;
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92026.img_ISU_ENG_SYMBL_onclick" });
    }
};

/**
 * @method
 * @name img_ISU_DD_onclick
