/**
 * @method
 * @name dts_Isu_OnLoadCompleted
 * @description dts_Isu 로드 완료 후처리(레거시 Gauce 이벤트 — 순차 스타일에서는 await 뒤에서 호출)
 * @param {*} rowcount rowcount
 * @returns {void}
 * @hidden N
 */
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.vBzProcsNo === "") {
            buttonSet.setInsertStatus();
            scwin.initForm('C');
        } else {
            scwin.initForm('X');
            let vCurDate = $c.date.getServerDateTime("yyyymmdd");
            if (ibx_LIST_DD.getValue() > vCurDate) {
                buttonSet.setUpdateStatus();
            } else {
                buttonSet.setErrorStatus(); // disable 시킨다.

            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92026.dts_Isu_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description trs_Save 트랜잭션 실패 콜백(레거시 Gauce)
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        scwin.alertJobMsg('F');
        $c.win.alert(trs_Save);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92026.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description trs_Save 트랜잭션 성공 콜백(레거시 Gauce)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        scwin.alertJobMsg('S');
        scwin.parentRefresh();
        if (buttonSet.status === "U") {
            let parentWin = $c.win.getParent();
            parentWin.dts_Isu.setFocusedCell(rowPos, 0);
        }
        if (buttonSet.status === "D") {
            // 삭제처리의 응답인 경우
            await $c.win.closePopup();
        } else {
            scwin.readSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92026.trs_Save_OnSuccess" });
    }
};

