};

/**
 * @method
 * @name sbx_NPARVALSTK_YN_onselchange
 * @description 무액면주식 onSelChage
 * @returns {void}
 * @hidden N
 */
scwin.sbx_NPARVALSTK_YN_onselchange = function() {
    try {
        if (scwin.vSecugrpID === $c.lc.getGlbValue("SECUGRP_ID_DR") ) {
            return;
        }
        if ( sbx_NPARVALSTK_YN.getValue() === "Y" ) {
            ibx_PARVAL.hide();
            ibx_PER1STK_CAP.show()
            ibx_PARVAL.setValue("0");
        } else {
            ibx_PARVAL.show();
            ibx_PER1STK_CAP.hide();
            ibx_PER1STK_CAP.setValue("0");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92026.sbx_NPARVALSTK_YN_onselchange" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 저장버튼클릭 — 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function (e) {
