 * @returns {Promise<void>}
 * @hidden N
 */
scwin.prtdepoReadSync = async function() {

    const searchReq = {"bzProcsNo" : "20180927000023"}

    const sbmOptions = {
        id : "sbm_dutyList",
        action : "/api/listing/lstproc/newlist-isu/select-list-prtdepo",
        method : "get",
        target : "dlt_dutyListRes=body",
        isProcessMsg : true
    };

    const res =  await $c.sbm.executeDynamic(sbmOptions, searchReq);
