        if (dlt_dutyListRes.getRowCount() > 0) {
            dlt_dutyListRes.setBroadcast(false);
            for( let i = 0; i <= dlt_dutyListRes.getRowCount(); i ++) {
                dlt_dutyListRes.setCellData(i, "seq", i);
            }
            dlt_dutyListRes.setBroadcast(true, true);
        }

    }

};

