 * @param {Object} obj 객체
 * @param {String|Number} val 값
 * @returns {void}
 * @hidden N
 */
scwin.setCheckboxData = function(obj, val) {
    if (val === 'Y') {
        obj.setValue(1);
    } else {
        obj.setValue(0);
    }
};

/**
 * @method
 * @name getCheckboxData
 * @description 데이터 값으로 체크박스 선택 상태를 설정한다.
 * @param {Object} obj 객체
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.getCheckboxData = function(obj) {
    if (obj.checked) {
        return 'Y';
    } else {
        return 'N';
    }
};

