/**
 * @method
 * @name save
 * @description 입력값을 저장한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {

    if (dlt_dutyListRes.getRowCount() === "0") {
        const  msg = "의무보유내역이 입력되지 않았습니다!\n의무보유대상이 있으면 취소를 누르고 해당내역을 입력하여 주십시오.\n그대로 진행하기를 원하시면 확인을 누르십시오.";
        const res = await $c.win.confirm(msg);
        if (!res) {
            return;
        }
    }

    scwin.TR_JOB = 'I';

    if (await scwin.checkForm()) {
        if ( !(await $c.lc.isProcess(scwin.TR_JOB)) ) return;
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo ();  // 신규상장번호생성

        if (String(scwin.vBzProcsNo).length !== 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            dlt_dutyListRes.setCellData(0, "bzProcsNo", scwin.vBzProcsNo);
            scwin.trs( scwin.TR_JOB);
        }
    }
};

/**
 * @method
 * @name update
 * @description 입력값을 수정 저장한다.
 * @returns {void}
 * @hidden N
 */
scwin.update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.checkForm()) {
        if (!$c.lc.isProcess(scwin.TR_JOB)) return;
        scwin.trs(scwin.TR_JOB);
    }
};

/**
 * @method
 * @name getCheckboxNprefStk
 * @description 신형우선주 체크박스 선택값을 구한다.
 * @param {Object} obj 객체
 * @param {*} stk_knd stk_knd
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.getCheckboxNprefStk = function(obj, stk_knd) {
    let val;
    if (obj.checked) {
        val = '2';
    } else {
        if (stk_knd === "000" || stk_knd === "KDR") {
            val = '0';
        } else {
            val = '1';
        }
    }
    return val;
};

