/**
 * @method
 * @name calcuAccIsuShrs
 * @description 증감주식수 계
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calcuAccIsuShrs = async function() {
    try {

        const bf_acc_isu_shrs = ibx_BF_ACC_ISU_SHRS.getValue();
        const isu_shrs = ibx_ISU_SHRS.getValue();

        const val1 = isNaN(parseInt(bf_acc_isu_shrs)) ? 0 : parseInt(bf_acc_isu_shrs);
        const val2 = isNaN(parseInt(isu_shrs)) ? 0 : parseInt(isu_shrs);

        let vsum = val1 + val2;
        // $c.win.alert( "[vsum]"+vsum);
        ibx_ACC_ISU_SHRS.setValue(vsum);
    } catch (err) {
        await $c.win.alert("[변경후 상장증권수 계산 중 오류]" + err);
    }
};

/**
 * @method
 * @name calcusuCap
 * @description calcusuCap
 * @returns {void}
 * @hidden N
 */
scwin.calcusuCap = function() {

    if (scwin.vSecugrpID === $c.lc.getGlbValue($p, "SECUGRP_ID_DR")) {
        ibx_ISU_CAP.setVAlue("");
    } else {
        try {
            const vRsnCd = sbx_STK_ISU_RSN_CD.getValue();
            let vsum = 0;
            if (vRsnCd === '118' || // 이익소각
                vRsnCd === '160' || // 상호변경
                vRsnCd === '170' || // 약면변합
                vRsnCd === '171') {
                // 액면분할
                vsum = 0; // 유가

            } else if (vRsnCd === '626' || // 이익소각
                vRsnCd === '643' || // 상호변경
                vRsnCd === '640' || // 약면변합
                vRsnCd === '641') {
                // 액면분할
                vsum = 0; // 코스닥

            } else {
                if ( scwin.vSecugrpID === $c.lc.getGlbValue("SECUGRP_ID_MF") || scwin.vSecugrpID === $c.lc.getGlbValue("SECUGRP_ID_IF")) {

                        const isu_prc  = ibx_ISU_PRC.getValue();
                        const isu_shrs = ibx_ISU_SHRS.getValue();

                        const val1 = isNaN(parseInt(isu_prc)) ? 0 : parseInt(isu_prc);
                        const val2 = isNaN(parseInt(isu_shrs)) ? 0 : parseInt(isu_shrs)

                        vsum = val1 + val2;
                } else {

                        const ibx_ParVal = ibx_PARVAL.getValue();
                        const isu_shrs = ibx_ISU_SHRS.getValue();

                        const val1 = isNaN(parseInt(ibx_ParVal)) ? 0 : parseInt(ibx_ParVal);
                        const val2 = isNaN(parseInt(isu_shrs)) ? 0 : parseInt(isu_shrs)

                        vsum = val1 + val2;
                }
            }
            // $c.win.alert( "[증감자본금 vsum]"+vsum);
            ibx_ISU_CAP.setValue(vsum);
        } catch (err) {
            $c.win.alert("[증감 상장자본금 계산 중  오류]" + err);
        }
    }
};

/**
 * @method
 * @name calcuAccIsuCap
 * @description 변경후 상장자본금
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calcuAccIsuCap = async function() {
    if (scwin.vSecugrpID === $c.lc.getGlbValue("SECUGRP_ID_DR") ) {
        ibx_ACC_ISU_CAP.setValue("");
    } else {
        try {
            const vRsnCd = sbx_STK_ISU_RSN_CD.getValue();
            let vsum = '';
            if (vRsnCd === '118' || // 이익소각
                vRsnCd === '160' || // 상호변경
                vRsnCd === '170' || // 약면변합
                vRsnCd === '171') {
                // 액면분할
                vsum = ibx_BF_ACC_ISU_CAP.getValue(); // 유가
                ibx_ISU_CAP.setValue(0); // 유가

            } else if (vRsnCd === '626' || // 이익소각
                vRsnCd === '643' || // 상호변경
                vRsnCd === '640' || // 약면변합
                vRsnCd === '641') {
                // 액면분할
                vsum = ibx_BF_ACC_ISU_CAP.getValue(); // 코스닥
                ibx_ISU_CAP.setValue(0); // 코스닥

            } else {
                await scwin.calcusuCap();

                const ibx_bf_acc_isu_cap = ibx_BF_ACC_ISU_CAP.getValue();
                const ibx_isu_cap = ibx_ISU_CAP.getValue();

                const val1 = isNaN(parseInt(ibx_bf_acc_isu_cap)) ? 0 : parseInt(ibx_bf_acc_isu_cap);
                const val2 = isNaN(parseInt(ibx_isu_cap)) ? 0 : parseInt(ibx_isu_cap)

                vsum = val1 + val2;

            }
            ibx_ACC_ISU_CAP.setValue(vsum);
        } catch (err) {
            $c.win.alert("[변경후 상장자본금 계산 중  오류]" + err);
        }
    }
};

/**
 * @method
 * @name openDetailPrtdepo
 * @description 보호예수신규등록시
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetailPrtdepo = async function(row) {

    if ( row > -1) {
        // 그리드에서 선택시
        scwin.gPrtdepoSeq = row;
    } else {
        // 신규버튼 선택시
        scwin.gPrtdepoSeq = ""; // 초기화

    }

    const data = {
        isuKorNm: ibx_ISU_KOR_NM.getValue(),
        gPrtdepoSeq: scwin.gPrtdepoSeq,
        gDtsObj: dlt_dutyListRes.getRowJSON(scwin.gPrtdepoSeq),
    };

    const opts = {
        id: "ULDSTF92025",
        popupName: "의무보유 등록/수정",
        width: 900,
        height: 650,
        frameModal: "top",
        type: "pageFramePopup",
    };
    const res = await $c.win.openPopup("/ui/lst/common/ULDSTF92025.xml", opts, data);
    if (res.flag === "D") {
        dlt_dutyListRes.removeRow(res.seq);
    } else if(res.flag !== "D" && res !== "") {
        dlt_dutyListRes.insertRow(0);
        dlt_dutyListRes.setRowJSON(0, res, true);
    }

};

/**
 * @method
 * @name prtdepoReadSyncSetHeader
 * @description 보호예수초기화
 * @returns {void}
 * @hidden N
 */
scwin.prtdepoReadSyncSetHeader = function() {
    dlt_dutyListRes.removeAll();
};

/**
 * @method
 * @name alertJobMsg
 * @description 처리 결과 안내 — 처리구분(TR_JOB: I/U/D/R/DSCL)에 맞는 작업명으로 성공(S: MSG-A001, S1: MSG-0001)·실패(F: MSG-A002) 메시지를 표시한다.
 * @param {String} gubun 결과 구분 (S | S1 | F)
 * @returns {Promise} $c.win.alert 반환값
 * @hidden N
 * @example scwin.alertJobMsg("S");
 */
scwin.alertJobMsg = function (gubun) {
    const job = (typeof scwin.TR_JOB !== "undefined") ? scwin.TR_JOB : "";
    const jobNm = { I : "저장", U : "수정", D : "삭제", R : "해제", DSCL : "안내문작성" }[job] || "";
    const code = (gubun === "S") ? "MSG-A001" : ((gubun === "S1") ? "MSG-0001" : "MSG-A002");
    return $c.win.alert($c.stf.getMessageParam(code, jobNm));
};
